    enonce: "بيّن أنّ العدد <span dir=\"ltr\" class=\"expr\">2<sup>59</sup> + 2<sup>61</sup></span> يقبل القسمة على 10",
    correction: [{"quoi":"القاعدة","math":"نضع أصغر قوّة عاملا مشتركا، فيبقى داخل القوس عدد صغير"},{"quoi":"نُظهر العامل المشترك","math":"<span dir=\"ltr\" class=\"expr\">2<sup>61</sup> = 2<sup>59</sup> × 2<sup>2</sup></span>"},{"quoi":"نُخرج العامل المشترك","math":"<span dir=\"ltr\" class=\"expr\">2<sup>59</sup> + 2<sup>61</sup> = 2<sup>59</sup>(1 + 2<sup>2</sup></span>"},{"quoi":"نحسب داخل القوس","math":"<span dir=\"ltr\" class=\"expr\">1 + 2<sup>2</sup> = 5</span>"},{"quoi":"نكتب الجداء","math":"<span dir=\"ltr\" class=\"expr\">2<sup>59</sup> + 2<sup>61</sup> = 5 × 2<sup>59</sup></span>"},{"quoi":"نُظهر القاسم 10","math":"<span dir=\"ltr\" class=\"expr\">5 × 2<sup>59</sup> = 10 × 2<sup>58</sup></span>"},{"quoi":"النتيجة","math":"العدد يساوي <span dir=\"ltr\" class=\"expr\">10 × 2<sup>58</sup></span> و منه يقبل القسمة على 10"}],
