    enonce: "بيّن أنّ العدد <span dir=\"ltr\" class=\"expr\">3<sup>69</sup> + 81<sup>18</sup></span> يقبل القسمة على 7",
    correction: [{"quoi":"القاعدة","math":"نضع أصغر قوّة عاملا مشتركا، فيبقى داخل القوس عدد صغير"},{"quoi":"نوحّد الأساس","math":"<span dir=\"ltr\" class=\"expr\">81<sup>18</sup> = 3<sup>72</sup></span>"},{"quoi":"نُظهر العامل المشترك","math":"<span dir=\"ltr\" class=\"expr\">3<sup>72</sup> = 3<sup>69</sup> × 3<sup>3</sup></span>"},{"quoi":"نُخرج العامل المشترك","math":"<span dir=\"ltr\" class=\"expr\">3<sup>69</sup> + 3<sup>72</sup> = 3<sup>69</sup>(1 + 3<sup>3</sup></span>"},{"quoi":"نحسب داخل القوس","math":"<span dir=\"ltr\" class=\"expr\">1 + 3<sup>3</sup> = 28</span>"},{"quoi":"نكتب الجداء","math":"<span dir=\"ltr\" class=\"expr\">3<sup>69</sup> + 81<sup>18</sup> = 28 × 3<sup>69</sup></span>"},{"quoi":"نُظهر القاسم 7","math":"<span dir=\"ltr\" class=\"expr\">28 × 3<sup>69</sup> = 7 × (4 × 3<sup>69</sup></span>"},{"quoi":"النتيجة","math":"العدد يساوي <span dir=\"ltr\" class=\"expr\">7 × 4 × 3<sup>69</sup></span> و منه يقبل القسمة على 7"}],
