    correction: [{"quoi":"نوحّد الأساس","math":"<span dir=\"ltr\" class=\"expr\">8<sup>8</sup> = 2<sup>24</sup></span>"},{"quoi":"نعيد كتابة الجداء","math":"<span dir=\"ltr\" class=\"expr\">(2<sup>23</sup> - 8<sup>8</sup> × 121 = (2<sup>23</sup> - 2<sup>24</sup> × 121</span>"},{"quoi":"نُخرج العامل المشترك","math":"<span dir=\"ltr\" class=\"expr\">(2<sup>23</sup> - 2<sup>24</sup> × 121 = 2<sup>23</sup>(1 - 2) × 121</span>"},{"quoi":"نحسب داخل القوس","math":"<span dir=\"ltr\" class=\"expr\">1 - 2 = -1</span>"},{"quoi":"نضرب في 121","math":"<span dir=\"ltr\" class=\"expr\">-1 × 121 = -121</span>"},{"quoi":"نكتب الجداء","math":"<span dir=\"ltr\" class=\"expr\">(2<sup>23</sup> - 8<sup>8</sup> × 121 = -121 × 2<sup>23</sup></span>"},{"quoi":"نُظهر القاسم 121","math":"<span dir=\"ltr\" class=\"expr\">-121 × 2<sup>23</sup> = 121 × (-2<sup>23</sup></span>"},{"quoi":"الباقي","math":"الجداء مضاعف لـ 121 فباقي القسمة يساوي 0"},{"quoi":"الخارج","math":"الخارج هو <span dir=\"ltr\" class=\"expr\">-2<sup>23</sup></span>"}],
