    correction: [{"quoi":"نستعمل الشكل المختصر","math":"<span dir=\"ltr\" class=\"expr\">M = 8 + 24/(-17 + 9)</span>"},{"quoi":"نحسب المقام","math":"<span dir=\"ltr\" class=\"expr\">-17 + 9 = -8</span>"},{"quoi":"نحسب الكسر","math":"<span dir=\"ltr\" class=\"expr\">24 : -8 = -3</span>"},{"quoi":"نجمع","math":"<span dir=\"ltr\" class=\"expr\">8 + -3 = 5</span>"},{"quoi":"نتحقّق بالشكل الأوّل","math":"<span dir=\"ltr\" class=\"expr\">(8 × -17 + 96)/(-17 + 9) = 5</span>"},{"quoi":"النتيجة","math":"<span dir=\"ltr\" class=\"expr\">M = 5</span>"}],
